// Message 回傳 code 對應的錯誤訊息；未登錄的碼回空字串，由呼叫端決定
// 要顯示什麼。這裡不回 fallback 字串：一句「未知錯誤」會蓋掉呼叫端原本
// 就有的碼值，而顯示原碼至少還追得到。
func Message(code int32) string {
	return bizCodeMessages[code]
}
